CREATE TABLE IF NOT EXISTS schema_versions(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,homepage TEXT NOT NULL,kind TEXT NOT NULL,category TEXT NOT NULL,language TEXT NOT NULL DEFAULT 'en',interval_minutes INTEGER NOT NULL DEFAULT 360,enabled INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'unverified',first_success TEXT,last_attempt TEXT,last_success TEXT,error TEXT,etag TEXT,last_modified TEXT,policy TEXT NOT NULL,count INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS items(id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),title TEXT NOT NULL,url TEXT NOT NULL UNIQUE,title_key TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',published_at TEXT,collected_at TEXT NOT NULL,kind TEXT NOT NULL,category TEXT NOT NULL,tags TEXT NOT NULL,score REAL NOT NULL,score_detail TEXT NOT NULL,rule_version TEXT NOT NULL,pdf_url TEXT,related_key TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS items_published ON items(published_at DESC);
CREATE INDEX IF NOT EXISTS items_source_date ON items(source_id,published_at);
CREATE INDEX IF NOT EXISTS items_kind_category ON items(kind,category,published_at);
CREATE INDEX IF NOT EXISTS items_score ON items(score DESC);
CREATE INDEX IF NOT EXISTS items_title ON items(title_key);
CREATE VIRTUAL TABLE IF NOT EXISTS item_search USING fts5(id UNINDEXED,title,summary,tokenize='unicode61');
CREATE TABLE IF NOT EXISTS runs(id TEXT PRIMARY KEY,source_id TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT NOT NULL,status TEXT NOT NULL,fetched INTEGER NOT NULL DEFAULT 0,inserted INTEGER NOT NULL DEFAULT 0,duplicates INTEGER NOT NULL DEFAULT 0,filtered INTEGER NOT NULL DEFAULT 0,invalid INTEGER NOT NULL DEFAULT 0,error TEXT);
CREATE INDEX IF NOT EXISTS runs_source_date ON runs(source_id,started_at);
CREATE TABLE IF NOT EXISTS series(id TEXT PRIMARY KEY,name TEXT NOT NULL,unit TEXT NOT NULL,frequency TEXT NOT NULL,provider TEXT NOT NULL,url TEXT NOT NULL,is_forecast INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'unverified',updated_at TEXT,error TEXT);
CREATE TABLE IF NOT EXISTS observations(series_id TEXT NOT NULL REFERENCES series(id),date TEXT NOT NULL,value REAL NOT NULL,collected_at TEXT NOT NULL,PRIMARY KEY(series_id,date));
CREATE TABLE IF NOT EXISTS indicator_runs(id TEXT PRIMARY KEY,series_id TEXT NOT NULL,started_at TEXT NOT NULL,status TEXT NOT NULL,count INTEGER NOT NULL DEFAULT 0,error TEXT);
CREATE TABLE IF NOT EXISTS records(user_id TEXT NOT NULL,item_id TEXT NOT NULL REFERENCES items(id),bookmarked INTEGER NOT NULL DEFAULT 0,read INTEGER NOT NULL DEFAULT 0,note TEXT NOT NULL DEFAULT '',tags TEXT NOT NULL DEFAULT '',project TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL,PRIMARY KEY(user_id,item_id));
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at TEXT NOT NULL,csrf TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts(key_hash TEXT PRIMARY KEY,count INTEGER NOT NULL DEFAULT 0,window_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS collection_lock(id TEXT PRIMARY KEY,owner TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS forecast_releases(id TEXT PRIMARY KEY,source_id TEXT NOT NULL,series_id TEXT NOT NULL,target_period TEXT NOT NULL,released_at TEXT NOT NULL,value REAL NOT NULL,unit TEXT NOT NULL,original_url TEXT NOT NULL,UNIQUE(source_id,series_id,target_period,released_at));
CREATE TABLE IF NOT EXISTS source_candidates(id TEXT PRIMARY KEY,name TEXT NOT NULL,url TEXT NOT NULL,method TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'unverified',checked_at TEXT,error TEXT,note TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS article_features(item_id TEXT NOT NULL REFERENCES items(id),version TEXT NOT NULL,input_hash TEXT NOT NULL,available_at TEXT NOT NULL,published_day TEXT,collected_day TEXT NOT NULL,industries TEXT NOT NULL,keywords TEXT NOT NULL,label TEXT NOT NULL,positive TEXT NOT NULL,negative TEXT NOT NULL,uncertainty TEXT NOT NULL,score REAL NOT NULL,score_detail TEXT NOT NULL,evaluated_at TEXT NOT NULL,processed_at TEXT NOT NULL,backfill INTEGER NOT NULL,PRIMARY KEY(item_id,version));
CREATE INDEX IF NOT EXISTS features_available ON article_features(version,collected_day);
CREATE TABLE IF NOT EXISTS article_keywords(item_id TEXT NOT NULL,version TEXT NOT NULL,keyword TEXT NOT NULL,industry TEXT NOT NULL,PRIMARY KEY(item_id,version,keyword,industry));
CREATE INDEX IF NOT EXISTS article_keyword_lookup ON article_keywords(version,industry,keyword);
CREATE TABLE IF NOT EXISTS research_daily(day TEXT NOT NULL,source_id TEXT NOT NULL,industry TEXT NOT NULL,keyword TEXT NOT NULL,version TEXT NOT NULL,n INTEGER NOT NULL,positive INTEGER NOT NULL,negative INTEGER NOT NULL,mixed INTEGER NOT NULL,uncertain INTEGER NOT NULL,neutral INTEGER NOT NULL,backfill INTEGER NOT NULL,computed_at TEXT NOT NULL,PRIMARY KEY(day,source_id,industry,keyword,version));
CREATE TABLE IF NOT EXISTS research_dictionary(version TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(version,kind));
CREATE TABLE IF NOT EXISTS industry_events(id TEXT PRIMARY KEY,event_type TEXT NOT NULL,event_date TEXT,announcement_date TEXT,company TEXT,country TEXT,industry TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,detected_keywords TEXT NOT NULL,source_url TEXT NOT NULL,source_id TEXT NOT NULL,confidence_level TEXT NOT NULL,verification_status TEXT NOT NULL DEFAULT 'unverified',amount_text TEXT,version TEXT NOT NULL,detected_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS event_sources(event_id TEXT NOT NULL REFERENCES industry_events(id),item_id TEXT NOT NULL REFERENCES items(id),PRIMARY KEY(event_id,item_id));
CREATE TABLE IF NOT EXISTS event_reviews(user_id TEXT NOT NULL,event_id TEXT NOT NULL REFERENCES industry_events(id),verification_status TEXT NOT NULL,event_date TEXT,company TEXT,country TEXT,note TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(user_id,event_id));
CREATE TABLE IF NOT EXISTS observation_vintages(series_id TEXT NOT NULL,observation_date TEXT NOT NULL,available_at TEXT NOT NULL,value REAL NOT NULL,availability_basis TEXT NOT NULL,PRIMARY KEY(series_id,observation_date,available_at));
CREATE INDEX IF NOT EXISTS vintages_available ON observation_vintages(series_id,available_at);
CREATE TABLE IF NOT EXISTS detected_signals(id TEXT PRIMARY KEY,signal_type TEXT NOT NULL,industry TEXT NOT NULL,subject TEXT NOT NULL,period_end TEXT NOT NULL,value REAL,threshold REAL,comparison TEXT NOT NULL,evidence TEXT NOT NULL,version TEXT NOT NULL,detected_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS analysis_runs(id TEXT PRIMARY KEY,version TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL,processed INTEGER NOT NULL DEFAULT 0,error TEXT);
CREATE TABLE IF NOT EXISTS research_projects(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,name TEXT NOT NULL,description TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research_hypotheses(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,project_id TEXT NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL,specification TEXT NOT NULL,preregistered_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research_experiments(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,hypothesis_id TEXT,kind TEXT NOT NULL,config TEXT NOT NULL,result TEXT NOT NULL,data_hash TEXT NOT NULL,version TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS research_notes(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,project_id TEXT NOT NULL,title TEXT NOT NULL,note TEXT NOT NULL,item_ids TEXT NOT NULL,series_ids TEXT NOT NULL,chart TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS generated_reports(id TEXT PRIMARY KEY,period TEXT NOT NULL,start_date TEXT NOT NULL,end_date TEXT NOT NULL,version TEXT NOT NULL,data_hash TEXT NOT NULL,payload TEXT NOT NULL,generated_at TEXT NOT NULL,UNIQUE(period,start_date,end_date,version,data_hash));
CREATE TABLE IF NOT EXISTS janus_datasets(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,symbol TEXT NOT NULL,kind TEXT NOT NULL,source_url TEXT NOT NULL,availability_basis TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS janus_observations(dataset_id TEXT NOT NULL REFERENCES janus_datasets(id),day TEXT NOT NULL,value REAL NOT NULL,available_at TEXT NOT NULL,PRIMARY KEY(dataset_id,day));
CREATE TABLE IF NOT EXISTS duplicate_origins(url TEXT PRIMARY KEY,canonical_item_id TEXT NOT NULL REFERENCES items(id),source_id TEXT NOT NULL,title TEXT NOT NULL,published_at TEXT,collected_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS event_links(user_id TEXT NOT NULL,event_id TEXT NOT NULL REFERENCES industry_events(id),target_event_id TEXT NOT NULL REFERENCES industry_events(id),created_at TEXT NOT NULL,PRIMARY KEY(user_id,event_id));
CREATE INDEX IF NOT EXISTS research_daily_lookup ON research_daily(version,industry,day,keyword);
CREATE INDEX IF NOT EXISTS events_type_date ON industry_events(event_type,announcement_date);
CREATE TABLE IF NOT EXISTS feature_completion(item_id TEXT NOT NULL,version TEXT NOT NULL,completed_at TEXT NOT NULL,PRIMARY KEY(item_id,version));
